import type { AiAssistantProvider, AssistantContext, AssistantResponse } from "./ai.interface.js"

export class HeuristicAiProvider implements AiAssistantProvider {
  async generateResponse(prompt: string, context?: AssistantContext): Promise<AssistantResponse> {
    const q = prompt.toLowerCase()
    const ctx = context ?? {}

    const has = (...words: string[]) => words.some((w) => q.includes(w))

    const disclaimer =
      "This response is generated by a rule-based safety heuristic. It is not real-time surveillance and cannot replace emergency services (Call 112 in India)."

    // 1. Harassment & Cyber safety (check before generic help queries)
    if (has("harassment", "harass", "stalk", "blackmail", "online", "cyber", "troll", "abuse")) {
      return {
        text: "If you are facing harassment: prioritize your physical safety first. For online harassment or blackmail, take screenshots including usernames, timestamps, and URLs before blocking the individual. Never delete evidence. Official cyber reports can be filed at cybercrime.gov.in or by calling the National Cyber Helpline at 1930. For physical harassment in public, reach out to nearby staff and call 112 or 1091.",
        sources: [
          "National Cybercrime Reporting Portal (1930)",
          "Women Helpline (1091 / 181)",
          "Saheli Digital Safety Guide",
        ],
        provider: "heuristic_mock",
        isAiGenerated: false,
        disclaimer,
      }
    }

    // 2. Immediate danger or feeling unsafe
    if (has("unsafe", "danger", "scared", "follow", "followed", "emergency", "threat", "attacker")) {
      return {
        text: "If you feel unsafe or believe you are being followed: move immediately towards a well-lit, crowded place such as an open shop, pharmacy, or hotel reception. Call a trusted contact and keep them on the line. If you are in immediate danger, dial 112 right away. You can also start a check-in or live location share in Saheli so contacts can see your progress.",
        sources: [
          "Emergency Services (Call 112)",
          "National Women Helpline (1091)",
          "General De-escalation & Personal Safety Guidance",
        ],
        provider: "heuristic_mock",
        isAiGenerated: false,
        disclaimer,
      }
    }

    // 3. Disaster or weather alert query
    if (ctx.alert || has("disaster", "rain", "flood", "landslide", "weather", "alert")) {
      return {
        text: "In the simulated Shillong test fixtures, an IMD heavy-rain alert is active for East Khasi Hills. Avoid low-lying underpasses (such as near Route B / valley roads) because passability cannot be verified during rainstorms. Stay on main thoroughfares (like Route A), stay away from steep hillside slopes, and monitor local district disaster management announcements.",
        sources: [
          "Simulated IMD Weather Alert (Sample Fixture)",
          "Meghalaya State Disaster Management Authority Guidance",
        ],
        provider: "heuristic_mock",
        isAiGenerated: false,
        disclaimer,
      }
    }

    // 4. Route comparison or journey planning
    if (ctx.route || has("route", "routes", "journey", "walk", "travel", "plan", "night")) {
      if (ctx.night && !ctx.transport) {
        return {
          text: "At night when public transport is limited: prioritize routes with documented street lighting and open public establishments (like Route A). Never assume any route is completely safe. Avoid shortcuts through unlit alleys. Keep your phone charged, set a check-in interval, and share your live location with a trusted contact.",
          sources: ["Third-party lighting surveys (Sample)", "Open Public Places Registry", "Personal Safety Standards"],
          provider: "heuristic_mock",
          isAiGenerated: false,
          disclaimer,
        }
      }

      return {
        text: "When comparing routes, evaluate documented street lighting, transit frequency, and proximity to open public places (pharmacies, hospitals, open shops). Route A has more recorded supporting infrastructure in sample fixtures, while Route B is shorter but has unverified evening transport. Select the route that keeps you close to active public spaces.",
        sources: ["Sample Shillong Route Assessments", "Saheli Route Comparison Engine"],
        provider: "heuristic_mock",
        isAiGenerated: false,
        disclaimer,
      }
    }

    // 5. Shelter finder query
    if (has("shelter", "refuge", "stay", "safe place", "one stop", "sakhi")) {
      return {
        text: "The sample database includes the One Stop Centre (Sakhi) in East Khasi Hills (1.8 km away), which provides temporary stay, medical referrals, and legal counselling for women. It is accessible 24/7. However, road access may be impacted during heavy rainfall. Please call 181 to verify real-time availability and road conditions.",
        sources: [
          "Sakhi One Stop Centre (Simulated Fixture)",
          "National Women Helpline (181)",
        ],
        provider: "heuristic_mock",
        isAiGenerated: false,
        disclaimer,
      }
    }

    // 6. General safety inquiry fallback
    return {
      text: "Saheli provides tools to help you plan informed journeys, keep trusted contacts in the loop, and reach help quickly. You can compare routes based on lighting and public places, set automatic check-in timers, or trigger discreet SOS alerts. In any immediate emergency, dial 112.",
      sources: ["Saheli Personal Safety Handbook", "Emergency Helpline 112"],
      provider: "heuristic_mock",
      isAiGenerated: false,
      disclaimer,
    }
  }
}
